#include "actuatorsMock_actuatorsMockThread.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void actuatorsMock_actuatorsMockThread_initialize(void);
void actuatorsMock_actuatorsMockThread_notify(microkit_channel channel);
void actuatorsMock_actuatorsMockThread_timeTriggered(void);

volatile sb_queue_bool_1_t *tempPressureActuate_queue_1;
sb_queue_bool_1_Recv_t tempPressureActuate_recv_queue;
volatile sb_queue_bool_1_t *saturationActuate_queue_1;
sb_queue_bool_1_Recv_t saturationActuate_recv_queue;

#define PORT_FROM_MON 0

bool last_tempPressureActuate_payload;

bool get_tempPressureActuate(bool *data) {
  sb_event_counter_t numDropped;
  bool fresh_data;
  bool isFresh = sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &tempPressureActuate_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_tempPressureActuate_payload = fresh_data;
  }
  *data = last_tempPressureActuate_payload;
  return isFresh;
}

uintmax_t get_tempPressureActuate_num_invalid(void) {
  return sb_queue_bool_1_numInvalid((sb_queue_bool_1_Recv_t *) &tempPressureActuate_recv_queue);
}

bool last_saturationActuate_payload;

bool get_saturationActuate(bool *data) {
  sb_event_counter_t numDropped;
  bool fresh_data;
  bool isFresh = sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &saturationActuate_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_saturationActuate_payload = fresh_data;
  }
  *data = last_saturationActuate_payload;
  return isFresh;
}

uintmax_t get_saturationActuate_num_invalid(void) {
  return sb_queue_bool_1_numInvalid((sb_queue_bool_1_Recv_t *) &saturationActuate_recv_queue);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_bool_1_Recv_init(&tempPressureActuate_recv_queue, (sb_queue_bool_1_t *) tempPressureActuate_queue_1);

  sb_queue_bool_1_Recv_init(&saturationActuate_recv_queue, (sb_queue_bool_1_t *) saturationActuate_queue_1);

  actuatorsMock_actuatorsMockThread_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      actuatorsMock_actuatorsMockThread_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      actuatorsMock_actuatorsMockThread_notify(channel);
  }
}
